// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz the array length and two addresses that will be placed into the _tos array.
    // We use at least one fuzzed parameter to satisfy the requirement; the fuzzer will
    // supply values. We construct a _tos array in-test to control its contents/admissibility.
    function testFuzz_property(address a0, address a1, uint256 len) public {
        // Keep len small but allow >1 so the mutant can be detected; bound keeps domain wide
        uint256 n = bound(len, 1, 8); // admissible: at least 1 element as require(_tos.length>0)

        // Deploy a recorder helper that implements transferFrom(address,address,uint256)
        // and records each call in an array. This lets us observe how many calls C made
        // and with what arguments. A raw EOA address would not record calls, so we need this.
        Recorder rec = new Recorder();

        // Build the _tos array with up to n entries. Use the two fuzzed addresses repeatedly
        // so the fuzzer still controls contents via a0 and a1.
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = (i % 2 == 0) ? a0 : a1;
        }

        // Call C.transfer, directing it to the recorder contract. We expect no revert.
        bool ok;
        try c.transfer(address(this), address(rec), tos, 123) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference implementation always returns true (and will not revert given our inputs),
        // so ok should be true. But more importantly we assert the universal property about call count.
        assertTrue(ok);

        // Now assert the general rule: recorder observed exactly n calls (one per tos entry).
        // The mutant that starts loop at i=1 will record n-1 calls when n>1, violating this.
        assertTrue(rec.count() == int(n));
    }
}

// Recorder that matches the exact selector C uses: transferFrom(address,address,uint256)
// It records each call's decoded arguments in arrays so the test can inspect the number
// of calls and their parameters. This is the adversarial/observing counterpart required
// because low-level calls to an EOA would not be recorded.
contract Recorder {
    address[] public froms;
    address[] public tos;
    uint256[] public vals;

    // The function signature must match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        froms.push(from);
        tos.push(to);
        vals.push(v);
        return true;
    }

    // helper getter that returns the call count as an int (so test can compare easily)
    function count() external view returns (int) {
        return int(froms.length);
    }
}
